import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import java.math.BigDecimal;
import java.util.regex.Pattern;

public class TransferFundsRQFmtMapper {

    private static final XmlMapper XML_MAPPER = new XmlMapper();

    public static TransferFundsRQFmtXml parseWire(String xmlContent) throws Exception {
        return XML_MAPPER.readValue(xmlContent, TransferFundsRQFmtXml.class);
    }

    public static String serializeWire(TransferFundsRQFmtXml wire) throws Exception {
        return XML_MAPPER.writeValueAsString(wire);
    }

    public static TransferFundsRQBusinessInput toBusinessInput(TransferFundsRQFmtXml wire) {
        if (wire == null) {
            return null;
        }

        TransferFundsRQBusinessInput businessInput = new TransferFundsRQBusinessInput();

        // SourceAccount: CCPadding (padChar='0', length=10, padLeft=true), CCMandatory
        String src = wire.getSourceAccount();
        src = removePadding(src, '0', 10, true);
        businessInput.setSourceAccount(src);

        // TargetAccount: CCPadding (padChar='0', length=10, padLeft=true), CCMandatory
        String tgt = wire.getTargetAccount();
        tgt = removePadding(tgt, '0', 10, true);
        businessInput.setTargetAccount(tgt);

        // Amount: NumberFormat (showThousandsSep=no, showDecimalsSep=yes), CCMandatory
        BigDecimal amt = wire.getAmount();
        businessInput.setAmount(amt);

        // Currency: CCPadding (padChar=' ', length=3, padLeft=true)
        String cur = wire.getCurrency();
        cur = removePadding(cur, ' ', 3, true);
        businessInput.setCurrency(cur);

        // SessionToken: MaskLogDecorator, CCMandatory
        String token = wire.getSessionToken();
        businessInput.setSessionToken(token);

        // TransferReference: nilDecorator
        String ref = wire.getTransferReference();
        if (ref == null) {
            ref = "";
        }
        businessInput.setTransferReference(ref);

        // ScheduledDate: nilDecorator
        String date = wire.getScheduledDate();
        if (date == null) {
            date = "";
        }
        businessInput.setScheduledDate(date);

        return businessInput;
    }

    public static TransferFundsRQFmtXml toWire(TransferFundsRQBusinessInput businessInput) {
        if (businessInput == null) {
            return null;
        }

        TransferFundsRQFmtXml wire = new TransferFundsRQFmtXml();

        // SourceAccount: forward decoration (add CCPadding)
        String src = businessInput.getSourceAccount();
        src = addPadding(src, '0', 10, true);
        wire.setSourceAccount(src);

        // TargetAccount: forward decoration
        String tgt = businessInput.getTargetAccount();
        tgt = addPadding(tgt, '0', 10, true);
        wire.setTargetAccount(tgt);

        // Amount
        wire.setAmount(businessInput.getAmount());

        // Currency: forward decoration
        String cur = businessInput.getCurrency();
        cur = addPadding(cur, ' ', 3, true);
        wire.setCurrency(cur);

        // SessionToken: MaskLogDecorator addDecoration is pass-through
        wire.setSessionToken(businessInput.getSessionToken());

        // TransferReference: nilDecorator addDecoration
        String ref = businessInput.getTransferReference();
        if (ref != null && ref.isBlank()) {
            ref = null;
        }
        wire.setTransferReference(ref);

        // ScheduledDate: nilDecorator addDecoration
        String date = businessInput.getScheduledDate();
        if (date != null && date.isBlank()) {
            date = null;
        }
        wire.setScheduledDate(date);

        return wire;
    }

    private static String removePadding(String value, char padChar, int length, boolean padLeft) {
        if (value == null) return null;
        if (padLeft) {
            return value.replaceFirst("^[" + Pattern.quote(String.valueOf(padChar)) + "]+", "");
        } else {
            return value.replaceFirst("[" + Pattern.quote(String.valueOf(padChar)) + "]+$", "");
        }
    }

    private static String addPadding(String value, char padChar, int length, boolean padLeft) {
        if (value == null) value = "";
        if (value.length() >= length) return value;
        String pad = String.valueOf(padChar).repeat(length - value.length());
        return padLeft ? pad + value : value + pad;
    }
}

package com.company.generated.units.u5ce9c9ef500c;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

public class TransferFundsRQFmtTest {

    @Test
    public void testUnformatAndFormatFlow() throws Exception {
        String xml = "<TransferFunds>" +
                "<SourceAccount>0000123456</SourceAccount>" +
                "<TargetAccount>0000987654</TargetAccount>" +
                "<Amount>150.50</Amount>" +
                "<Currency>USD</Currency>" +
                "<SessionToken>tok_abc123</SessionToken>" +
                "<TransferReference>REF999</TransferReference>" +
                "<ScheduledDate>2023-12-31</ScheduledDate>" +
                "</TransferFunds>";

        TransferFundsRQFmtXml wire = TransferFundsRQFmtMapper.parseWire(xml);
        assertNotNull(wire);
        assertEquals("0000123456", wire.getSourceAccount());

        TransferFundsRQBusinessInput input = TransferFundsRQFmtMapper.toBusinessInput(wire);
        assertNotNull(input);
        assertEquals("123456", input.getSourceAccount());
        assertEquals("987654", input.getTargetAccount());
        assertEquals(0, new BigDecimal("150.50").compareTo(input.getAmount()));
        assertEquals("USD", input.getCurrency());
        assertEquals("tok_abc123", input.getSessionToken());
        assertEquals("REF999", input.getTransferReference());
        assertEquals("2023-12-31", input.getScheduledDate());

        // Roundtrip back to wire
        TransferFundsRQFmtXml roundtripWire = TransferFundsRQFmtMapper.toWire(input);
        assertEquals("0000123456", roundtripWire.getSourceAccount());
        assertEquals("0000987654", roundtripWire.getTargetAccount());
        assertEquals("USD", roundtripWire.getCurrency());
        assertEquals("REF999", roundtripWire.getTransferReference());

        String serialized = TransferFundsRQFmtMapper.serializeWire(roundtripWire);
        assertNotNull(serialized);
        assertTrue(serialized.contains("<SourceAccount>0000123456</SourceAccount>"));
    }
}
